//go:build goexperiment.boringcrypto

package aesgcm

import (
	"crypto/boring"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/bincyber/go-sqlcrypter"
)

// Test_New_BoringCryptoFallback checks that when BoringCrypto supplies the AES
// block, New falls back to cipher.NewGCM with a nonce generated by this provider.
// BoringCrypto is only enabled on linux/amd64 and linux/arm64; elsewhere
// GOEXPERIMENT=boringcrypto builds but the standard library's AES is used.
func Test_New_BoringCryptoFallback(t *testing.T) {
	if !boring.Enabled() {
		t.Skip("BoringCrypto is not enabled on this platform")
	}

	key, _ := sqlcrypter.GenerateBytes(32)

	c, err := New(key, nil)
	require.NoError(t, err)

	a, ok := c.(*AESCrypter)
	require.True(t, ok)

	assert.Equal(t, 12, a.current.NonceSize())
	assert.Equal(t, 16, a.current.Overhead())

	plaintext := []byte("Hello World")
	got, err := decrypt(c, encrypt(t, c, plaintext))
	require.NoError(t, err)
	assert.Equal(t, plaintext, got)

	got, err = decrypt(c, legacySeal(t, key, plaintext))
	require.NoError(t, err)
	assert.Equal(t, plaintext, got)
}
